#[derive(Debug, Clone, Deserialize)]
struct SessionDetailResponse {
    ok: bool,
    #[serde(default)]
    session: Option<SessionDetail>,
    #[serde(default)]
    projection: Option<SessionProjection>,
    #[serde(default)]
    error: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionDetail {
    id: String,
    title: String,
    model: String,
    #[serde(default)]
    workspace_root: Option<String>,
    #[serde(default)]
    cwd: Option<String>,
    #[serde(default)]
    transcript: Vec<SessionTranscriptEntry>,
    /// Per-message tool-call/result context the daemon derives alongside the
    /// transcript. We read it to recover `component_render` props on reconnect:
    /// `ComponentRender` is an SSE-only side-channel event that is never folded
    /// into a transcript text entry, but the assistant tool-call that produced it
    /// IS persisted here with its full `arguments` (id/kind/props). Replaying
    /// those lets rendered components survive a mid-turn SSE reconnect instead of
    /// vanishing (OCEAN-382).
    #[serde(default)]
    tool_context: Vec<SessionToolContext>,
    #[serde(default)]
    pending_permissions: Vec<String>,
    /// Additive feature signal. `None` identifies an old daemon; `Some` with a
    /// temporarily absent projection is retried before legacy fallback.
    #[serde(default)]
    persistence_revision: Option<u64>,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionProjection {
    version: u32,
    cursor: String,
    checkpoint_revision: u64,
    #[serde(default)]
    checkpoint: Option<SessionProjectionCheckpoint>,
    lease_id: String,
    lease_expires_ms: i64,
    #[serde(default)]
    pending_events: Vec<SessionProjectionFrame>,
    #[serde(default)]
    state: SessionProjectionState,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionProjectionFrame {
    cursor: String,
    source: SessionProjectionSource,
    event: Value,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
enum SessionProjectionSource {
    Agent,
    Control,
    Checkpoint,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", deny_unknown_fields)]
enum SessionProjectionCheckpoint {
    #[serde(rename = "projection_checkpoint")]
    Inline {
        persistence_revision: u64,
        transcript: Vec<SessionTranscriptEntry>,
        tool_context: Vec<SessionToolContext>,
    },
    #[serde(rename = "projection_checkpoint_refetch")]
    Refetch { persistence_revision: u64 },
}

#[derive(Debug, Clone, Default, Deserialize)]
struct SessionProjectionState {
    #[serde(default)]
    active_turn: Option<Value>,
    #[serde(default)]
    last_turn_finished: Option<Value>,
    #[serde(default)]
    model_rerouted: Option<Value>,
    #[serde(default)]
    pending_permissions: Vec<Value>,
    #[serde(default)]
    browser_active: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProjectionCursor {
    prefix: String,
    seq: u64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CursorTransition {
    Duplicate,
    Next,
    Reset,
}

fn parse_projection_cursor(raw: &str) -> Option<ProjectionCursor> {
    let mut parts = raw.split(':');
    if parts.next()? != "sp1" {
        return None;
    }
    let epoch = parts.next()?;
    let session_hash = parts.next()?;
    let seq = parts.next()?.parse().ok()?;
    let epoch_bytes = epoch.as_bytes();
    let valid_epoch = epoch_bytes.len() == 36
        && epoch_bytes.iter().enumerate().all(|(index, byte)| {
            if matches!(index, 8 | 13 | 18 | 23) {
                *byte == b'-'
            } else {
                byte.is_ascii_hexdigit()
            }
        });
    if parts.next().is_some()
        || !valid_epoch
        || session_hash.len() != 16
        || !session_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
    {
        return None;
    }
    Some(ProjectionCursor {
        prefix: format!("sp1:{epoch}:{session_hash}"),
        seq,
    })
}

fn projection_cursor_transition(current: &str, incoming: &str) -> CursorTransition {
    let (Some(current), Some(incoming)) = (
        parse_projection_cursor(current),
        parse_projection_cursor(incoming),
    ) else {
        return CursorTransition::Reset;
    };
    if current.prefix != incoming.prefix {
        CursorTransition::Reset
    } else if incoming.seq <= current.seq {
        CursorTransition::Duplicate
    } else if incoming.seq == current.seq.saturating_add(1) {
        CursorTransition::Next
    } else {
        CursorTransition::Reset
    }
}

#[derive(Debug, Clone, Deserialize)]
struct PermissionsResponse {
    ok: bool,
    #[serde(default)]
    permissions: Vec<PermissionStatusWire>,
    #[serde(default)]
    error: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct PermissionStatusWire {
    permission_id: String,
    #[serde(default)]
    session_id: Option<String>,
    #[serde(default)]
    request_id: Option<String>,
    tool: String,
    reason: String,
    #[serde(default)]
    args: Value,
}

#[derive(Debug, Clone, Deserialize)]
struct SessionTranscriptEntry {
    role: String,
    #[serde(default)]
    text: String,
    /// Correlates a `tool` transcript entry with its originating `call` in
    /// `tool_context` (so a `component_render` result can be matched to the
    /// tool-call args carrying its props). `None` for non-tool entries.
    #[serde(default)]
    tool_call_id: Option<String>,
    #[serde(default)]
    tool_name: Option<String>,
    #[serde(default)]
    is_error: Option<bool>,
}

/// Tool-call / tool-result context for a persisted message, mirroring the
/// daemon's `SessionToolContext`. Ordered call/result pairing plus explicit
/// result success determines whether a component effect actually occurred.
#[derive(Debug, Clone, Deserialize)]
struct SessionToolContext {
    /// `"call"` or `"result"`.
    kind: String,
    tool_call_id: String,
    tool_name: String,
    #[serde(default)]
    arguments: Option<serde_json::Value>,
    /// Present on result entries. Component replay requires explicit success.
    #[serde(default)]
    is_error: Option<bool>,
}

#[derive(Debug)]
struct PreparedProjection {
    detail: SessionDetail,
    turns: Vec<Turn>,
    pinned: Vec<PinnedWidget>,
    cursor: String,
    lease_id: String,
    active_turn: Option<AgentEvent>,
    last_turn_finished: Option<AgentEvent>,
    model_rerouted: Option<AgentEvent>,
    permissions: Vec<PendingPermission>,
    browser_active: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProjectionPreparation {
    Restart,
    Invalid,
}

fn is_canvas_lane_event(event: &AgentEvent, session_id: &str) -> bool {
    matches!(event, AgentEvent::SurfacePatch { .. }) && event.session_id() == Some(session_id)
}

fn is_forbidden_projection_agent_event(event: &AgentEvent) -> bool {
    // The daemon intentionally excludes these best-effort side rails from the
    // durable session projection. Seeing one here is protocol corruption, not a
    // frame to accept while advancing the transcript cursor.
    matches!(
        event,
        AgentEvent::SurfacePatch { .. } | AgentEvent::Extension { .. }
    )
}

fn apply_component_projection_event(
    turns: &mut Vec<Turn>,
    pinned: &mut Vec<PinnedWidget>,
    event: &AgentEvent,
) {
    match event {
        AgentEvent::ComponentRender {
            component_id,
            kind,
            props,
            replace,
            ..
        } => {
            if component_placement(props) == ComponentPlacement::Pinned {
                upsert_pinned(
                    pinned,
                    PinnedWidget {
                        component_id: component_id.clone(),
                        kind: kind.clone(),
                        props: props.clone(),
                    },
                );
                return;
            }
            if *replace {
                for turn in turns.iter_mut() {
                    for block in turn.blocks.iter_mut() {
                        if matches!(block, Block::Component { component_id: id, .. } if id == component_id)
                        {
                            *block = Block::Component {
                                component_id: component_id.clone(),
                                kind: kind.clone(),
                                props: props.clone(),
                            };
                            return;
                        }
                    }
                }
            }
            ensure_component_turn(turns).blocks.push(Block::Component {
                component_id: component_id.clone(),
                kind: kind.clone(),
                props: props.clone(),
            });
        }
        AgentEvent::ComponentUnmount { component_id, .. } => {
            for turn in turns.iter_mut() {
                turn.blocks.retain(|block| {
                    !matches!(block, Block::Component { component_id: id, .. } if id == component_id)
                });
            }
            turns.retain(|turn| !turn.blocks.is_empty());
            pinned.retain(|widget| widget.component_id != *component_id);
        }
        _ => {}
    }
}

fn apply_projection_content(
    turns: &mut Vec<Turn>,
    pinned: &mut Vec<PinnedWidget>,
    event: &AgentEvent,
) {
    match event {
        AgentEvent::AssistantTextDelta { turn_id, delta, .. } => {
            let turn = ensure_assistant_turn(turns, turn_id);
            match turn.blocks.last_mut() {
                Some(Block::Text(text)) => text.push_str(delta),
                _ => turn.blocks.push(Block::Text(delta.clone())),
            }
        }
        AgentEvent::ThinkingDelta { turn_id, delta, .. } => {
            let turn = ensure_assistant_turn(turns, turn_id);
            match turn.blocks.last_mut() {
                Some(Block::Thinking { content, .. }) => content.push_str(delta),
                _ => turn.blocks.push(Block::Thinking {
                    content: delta.clone(),
                    expanded: false,
                }),
            }
        }
        AgentEvent::ToolCallStarted { turn_id, call, .. } => {
            let args = serde_json::to_string(&call.args_json).unwrap_or_else(|_| "{}".into());
            ensure_assistant_turn(turns, turn_id)
                .blocks
                .push(Block::ToolCall {
                    call_id: call.id.clone(),
                    name: call.name.clone(),
                    args_preview: args.chars().take(60).collect(),
                    output: String::new(),
                    status: ToolStatus::Running,
                    expanded: false,
                });
        }
        AgentEvent::ToolCallChunk {
            turn_id,
            call_id,
            chunk,
            ..
        } => {
            for block in ensure_assistant_turn(turns, turn_id)
                .blocks
                .iter_mut()
                .rev()
            {
                if let Block::ToolCall {
                    call_id: id,
                    output,
                    ..
                } = block
                {
                    if id == call_id {
                        output.push_str(chunk);
                        break;
                    }
                }
            }
        }
        AgentEvent::ToolCallFinished {
            turn_id,
            call_id,
            result,
            ..
        } => {
            for block in ensure_assistant_turn(turns, turn_id)
                .blocks
                .iter_mut()
                .rev()
            {
                if let Block::ToolCall {
                    call_id: id,
                    output,
                    status,
                    expanded,
                    ..
                } = block
                {
                    if id == call_id {
                        if output.is_empty() {
                            output.push_str(&result.output);
                        }
                        *status = if result.ok {
                            ToolStatus::Ok
                        } else {
                            ToolStatus::Err
                        };
                        *expanded |= !result.ok;
                        break;
                    }
                }
            }
        }
        AgentEvent::ComponentRender { .. } | AgentEvent::ComponentUnmount { .. } => {
            apply_component_projection_event(turns, pinned, event);
        }
        _ => {}
    }
}

type ProjectionReplacement = (Vec<Turn>, Vec<PinnedWidget>);

fn checkpoint_replacement(
    checkpoint: &SessionProjectionCheckpoint,
) -> Result<Option<ProjectionReplacement>, ProjectionPreparation> {
    match checkpoint {
        SessionProjectionCheckpoint::Inline {
            transcript,
            tool_context,
            ..
        } => Ok(Some(turns_from_session_transcript(
            transcript.clone(),
            tool_context,
        ))),
        SessionProjectionCheckpoint::Refetch { .. } => Err(ProjectionPreparation::Restart),
    }
}

fn permission_from_projection(value: &Value, session_id: &str) -> Option<PendingPermission> {
    let event = serde_json::from_value::<ControlEvent>(value.clone()).ok()?;
    match event {
        ControlEvent::PermissionRequest {
            permission_id: Some(permission_id),
            session_id: Some(event_session),
            request_id,
            tool,
            reason,
            args,
        } if event_session == session_id => Some(PendingPermission {
            permission_id,
            session_id: event_session,
            request_id,
            tool,
            reason,
            args_summary: summarize_args(&args),
            deciding: false,
        }),
        _ => None,
    }
}

fn prepare_projection_snapshot(
    detail: SessionDetail,
    projection: SessionProjection,
) -> Result<PreparedProjection, ProjectionPreparation> {
    if projection.version != 1
        || projection.lease_id.is_empty()
        || projection.lease_expires_ms <= 0
        || detail.persistence_revision != Some(projection.checkpoint_revision)
    {
        return Err(ProjectionPreparation::Invalid);
    }
    if let Some(checkpoint) = &projection.checkpoint {
        let revision = match checkpoint {
            SessionProjectionCheckpoint::Inline {
                persistence_revision,
                ..
            }
            | SessionProjectionCheckpoint::Refetch {
                persistence_revision,
            } => *persistence_revision,
        };
        if revision != projection.checkpoint_revision {
            return Err(ProjectionPreparation::Invalid);
        }
    }
    let final_cursor =
        parse_projection_cursor(&projection.cursor).ok_or(ProjectionPreparation::Invalid)?;
    if projection.pending_events.len() as u64 > final_cursor.seq {
        return Err(ProjectionPreparation::Invalid);
    }
    let mut expected_seq = final_cursor.seq - projection.pending_events.len() as u64;
    let (mut turns, mut pinned) =
        turns_from_session_transcript(detail.transcript.clone(), &detail.tool_context);

    // The top-level refetch marker is already satisfied by this same canonical
    // GET. Inline checkpoints are an aligned normalized replacement.
    if let Some(checkpoint) = &projection.checkpoint {
        if let SessionProjectionCheckpoint::Inline { .. } = checkpoint {
            if let Some(replacement) = checkpoint_replacement(checkpoint)? {
                (turns, pinned) = replacement;
            }
        }
    }

    for frame in &projection.pending_events {
        let parsed =
            parse_projection_cursor(&frame.cursor).ok_or(ProjectionPreparation::Invalid)?;
        expected_seq = expected_seq.saturating_add(1);
        if parsed.prefix != final_cursor.prefix || parsed.seq != expected_seq {
            return Err(ProjectionPreparation::Invalid);
        }
        match frame.source {
            SessionProjectionSource::Agent => {
                let event = serde_json::from_value::<AgentEvent>(frame.event.clone())
                    .map_err(|_| ProjectionPreparation::Invalid)?;
                if event.session_id() != Some(detail.id.as_str())
                    || is_forbidden_projection_agent_event(&event)
                {
                    return Err(ProjectionPreparation::Invalid);
                }
                apply_projection_content(&mut turns, &mut pinned, &event);
            }
            SessionProjectionSource::Control => {
                // Folded permission state below is authoritative; reducing these
                // frames too would duplicate cards.
            }
            SessionProjectionSource::Checkpoint => {
                let checkpoint =
                    serde_json::from_value::<SessionProjectionCheckpoint>(frame.event.clone())
