        let implicit_result = vec![
            render_call(
                "c-1",
                serde_json::json!({ "id": "x", "kind": "card", "props": {} }),
            ),
            component_tool_result("c-1", None),
        ];
        assert!(component_replay_matches(&implicit_result).is_empty());

        let duplicate_call = vec![
            render_call(
                "c-1",
                serde_json::json!({ "id": "first", "kind": "card", "props": {} }),
            ),
            render_call(
                "c-1",
                serde_json::json!({ "id": "second", "kind": "card", "props": {} }),
            ),
            component_tool_result("c-1", Some(false)),
        ];
        assert!(component_replay_matches(&duplicate_call).is_empty());

        let reused_after_result = vec![
            render_call(
                "c-1",
                serde_json::json!({ "id": "first", "kind": "card", "props": {} }),
            ),
            component_tool_result("c-1", Some(false)),
            render_call(
                "c-1",
                serde_json::json!({ "id": "second", "kind": "card", "props": {} }),
            ),
            component_tool_result("c-1", Some(false)),
        ];
        assert!(component_replay_matches(&reused_after_result).is_empty());

        let repeated_result = vec![
            render_call(
                "c-1",
                serde_json::json!({ "id": "x", "kind": "card", "props": {} }),
            ),
            component_tool_result("c-1", Some(false)),
            component_tool_result("c-1", Some(false)),
